package com.nivor.workspace;
import com.nivor.workspace.dto.*;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/workspaces")public class WorkspaceController{
private final WorkspaceService service;public WorkspaceController(WorkspaceService s){service=s;}@GetMapping public List<WorkspaceResponse> list(@AuthenticationPrincipal UserDetails u){return service.list(u.getUsername()).stream().map(WorkspaceResponse::from).toList();}@GetMapping("/{id}")public WorkspaceResponse get(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){return WorkspaceResponse.from(service.get(u.getUsername(),id));}@PostMapping public ResponseEntity<WorkspaceResponse> create(@AuthenticationPrincipal UserDetails u,@Valid@RequestBody WorkspaceRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(WorkspaceResponse.from(service.create(u.getUsername(),r)));}@PutMapping("/{id}")public WorkspaceResponse update(@AuthenticationPrincipal UserDetails u,@PathVariable Long id,@Valid@RequestBody WorkspaceRequest r){return WorkspaceResponse.from(service.update(u.getUsername(),id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable Long id){service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}
}
